declare(strict_types=1);

use app\assets\BattleImageLazyLoadAsset;
use app\assets\PhotoSwipeAsset;
use yii\helpers\Html;
use yii\web\View;

/**
 * @var View $this
 * @var list<string> $imageUrls
 */

if ($imageUrls) {
  BattleImageLazyLoadAsset::register($this);
  PhotoSwipeAsset::register($this);

  // Both the uploaded images and the images generated by s3-img-gen are 16:9 (1280x720 at most).
  // The real size is set by battle-image-lazy-load.js after the image is loaded.
  echo Html::tag(
    'div',
    implode(
      '',
      array_map(
        fn (string $url): string => Html::tag(
          'div',
          Html::a(
            Html::tag(
              'span',
              Html::img($url, [
                'alt' => '',
                'decoding' => 'async',
                'height' => 720,
                'loading' => 'lazy',
                'width' => 1280,
              ]),
              ['class' => 'battle-image-frame battle-image-loading'],
            ),
            $url,
            [
              'data' => [
                'pswp-height' => 720,
                'pswp-width' => 1280,
              ],
            ],
          ),
          ['class' => 'col-xs-12 col-md-6 image-container mb-3'],
        ),
        $imageUrls,
      ),
    ),
    [
      'class' => 'row',
      'data' => [
        'pswp' => '',
      ],
    ],
  );
}
